create or replace function public.s3b_apply_act1_consequence()
returns trigger language plpgsql security definer set search_path=public as $$
declare v_role text;
begin
  if old.act1_choice_id is not null or new.act1_choice_id is null then return new; end if;
  select role_slot into strict v_role from public.s1_room_players where player_id=new.player_id;

  if v_role='GAL-A' then
    insert into public.s3b_player_facts values(new.run_id,new.player_id,'gitte_heard_chapel_warning',now()),(new.run_id,new.player_id,'gitte_knows_basic_map',now()),(new.run_id,new.player_id,'gitte_number_note_visible',now()) on conflict do nothing;
    perform public.s3_record_observation(new.run_id,new.player_id,'chapel_warning','act1_wake_up');
    if new.act1_choice_id='study_map' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'gitte_map_detail',now()) on conflict do nothing;
    elsif new.act1_choice_id='check_sound' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'gitte_saw_shadow',now()) on conflict do nothing; perform public.s3_record_observation(new.run_id,new.player_id,'corridor_shadow','act1_wake_up');
    elsif new.act1_choice_id='study_number_note' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'gitte_knows_star',now()) on conflict do nothing;
    elsif new.act1_choice_id='search_room' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'gitte_flashlight_found',now()) on conflict do nothing; end if;
  elsif v_role='GAL-B' then
    insert into public.s3b_player_facts values(new.run_id,new.player_id,'anna_knows_great_hall_lock',now()),(new.run_id,new.player_id,'anna_diary_visible',now()) on conflict do nothing;
    perform public.s3_record_observation(new.run_id,new.player_id,'great_hall_outer_lock','act1_wake_up');
    if new.act1_choice_id='read_diary' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'anna_knows_snake_rule',now()) on conflict do nothing;
    elsif new.act1_choice_id='check_door' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'anna_knows_library_passage',now()) on conflict do nothing;
    elsif new.act1_choice_id='check_phone' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'anna_detected_devices',now()) on conflict do nothing;
    elsif new.act1_choice_id='check_vent' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'anna_heard_vent_movement',now()) on conflict do nothing; perform public.s3_record_observation(new.run_id,new.player_id,'warm_vent_movement','act1_wake_up'); end if;
  else
    insert into public.s3b_player_facts values(new.run_id,new.player_id,'linda_watch_visible',now()),(new.run_id,new.player_id,'linda_star_key_visible',now()),(new.run_id,new.player_id,'linda_knows_tower_closed',now()),(new.run_id,new.player_id,'linda_closure_notice_visible',now()) on conflict do nothing;
    if new.act1_choice_id='read_notice' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'linda_knows_tower_reason',now()) on conflict do nothing;
    elsif new.act1_choice_id='study_watch' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'linda_knows_watch_message',now()) on conflict do nothing;
    elsif new.act1_choice_id='try_star_key' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'linda_tested_star_key',now()) on conflict do nothing;
    elsif new.act1_choice_id='check_mirror' then insert into public.s3b_player_facts values(new.run_id,new.player_id,'linda_knows_warm_air_warning',now()) on conflict do nothing; perform public.s3_record_observation(new.run_id,new.player_id,'warm_air_warning','act1_wake_up'); end if;
  end if;
  return new;
end; $$;

create or replace function public.s3b_add_optional_grab_item()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if not old.grab_complete and new.grab_complete and exists(select 1 from public.s3b_player_facts where run_id=new.run_id and player_id=new.player_id and fact_key='gitte_flashlight_found') then
    insert into public.s3_player_items(run_id,item_key,physical_owner_id) values(new.run_id,'gitte_flashlight',new.player_id) on conflict do nothing;
    insert into public.s3_player_item_view_state(run_id,player_id,item_key,current_view) values(new.run_id,new.player_id,'gitte_flashlight','front') on conflict do nothing;
  end if;
  return new;
end; $$;

create or replace function public.s3b_get_my_facts(p_room_code text,p_session_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_room text:=upper(trim(p_room_code)); v_player public.s1_room_players%rowtype; v_run public.game_runs%rowtype;
begin
  v_player:=public.s1_get_player_by_session(v_room,p_session_token); v_run:=public.s2_get_active_run(v_room);
  return (select coalesce(jsonb_agg(fact_key order by fact_key),'[]') from public.s3b_player_facts where run_id=v_run.run_id and player_id=v_player.player_id);
end; $$;

create or replace function public.s3b_canonicalize_group_item_label()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.item_key='library_photo_1897' then new.label_text_key:='item.photo_1897';
  elsif new.item_key='library_torn_note' then new.label_text_key:='item.torn_note'; end if;
  return new;
end; $$;

create or replace function public.s3b_guard_player_progress_phase()
returns trigger language plpgsql security definer set search_path=public as $$
declare v_scene public.s3_runtime_scene_state%rowtype;
begin
  select * into strict v_scene from public.s3_runtime_scene_state where run_id=new.run_id;
  if old.act1_choice_id is null and new.act1_choice_id is not null and not (v_scene.scene_id='act1_wake_up' and v_scene.phase_key='private_first_action') then raise exception 'ACT 1 choice is out of phase.'; end if;
  if old.first_meeting_choice is null and new.first_meeting_choice is not null and not (v_scene.scene_id='act2_first_contact' and v_scene.phase_key='private_first_meeting') then raise exception 'ACT 2 first meeting choice is out of phase.'; end if;
  if not old.grab_complete and new.grab_complete and not (v_scene.scene_id='act2_first_contact' and v_scene.phase_key='private_first_meeting') then raise exception 'GRAB is out of phase.'; end if;
  if not old.left_start_room and new.left_start_room and not (v_scene.scene_id='act2_first_contact' and v_scene.phase_key='private_first_meeting') then raise exception 'Leaving the start room is out of phase.'; end if;
  if old.player_location is distinct from new.player_location and new.player_location='library' and not (v_scene.scene_id='act3_library' and v_scene.phase_key='wayfinding') then raise exception 'FOLLOW SIGN is out of phase.'; end if;
  if old.act4_choice_id is null and new.act4_choice_id is not null and not (v_scene.scene_id='act4_known_unknown' and v_scene.phase_key='private_route_choice') then raise exception 'ACT 4 choice is out of phase.'; end if;
  return new;
end; $$;

create or replace function public.s3b_guard_run_state_phase()
returns trigger language plpgsql security definer set search_path=public as $$
declare v_scene public.s3_runtime_scene_state%rowtype;
begin
  select * into strict v_scene from public.s3_runtime_scene_state where run_id=new.run_id;
  if old.final_meeting_result is null and new.final_meeting_result is not null and not (v_scene.scene_id='act2_first_contact' and v_scene.phase_key='meeting_discussion') then raise exception 'Meeting resolution is out of phase.'; end if;
  if not old.party_physically_reunited and new.party_physically_reunited and not (v_scene.scene_id='act3_library' and v_scene.phase_key='wayfinding') then raise exception 'Party reunion is out of phase.'; end if;
  if (old.puzzle_attempt_number is distinct from new.puzzle_attempt_number or old.puzzle_hint_stage is distinct from new.puzzle_hint_stage or old.puzzle_resolved_at is distinct from new.puzzle_resolved_at)
    and not (v_scene.scene_id='act3_library' and v_scene.phase_key='library_box') then raise exception 'Library Box mutation is out of phase.'; end if;
  if old.group_route is distinct from new.group_route and new.group_route is not null
    and v_scene.scene_id not in ('act4_known_unknown','act5_route_discussion','act5_inspect_first') then raise exception 'Group route mutation is out of phase.'; end if;
  return new;
end; $$;

create or replace function public.s3b_guard_library_attempt_phase()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if not exists(select 1 from public.s3_runtime_scene_state where run_id=new.run_id and scene_id='act3_library' and phase_key='library_box') then raise exception 'Library Box attempt is out of phase.'; end if;
  return new;
end; $$;

create or replace function public.s3b_refresh_puzzle(p_run uuid) returns void language plpgsql security definer set search_path=public as $$
declare s public.s3b_run_state%rowtype;t int;n int;room text;k text;prefix text;
begin select * into s from public.s3b_run_state where run_id=p_run for update;if not found or s.puzzle_resolved_at is not null or s.puzzle_deadline is null or now()<s.puzzle_deadline then return;end if;t:=least(8,4+floor(extract(epoch from(now()-s.puzzle_deadline))/15)::int);select room_code into room from public.game_runs where run_id=p_run;for n in s.puzzle_hint_stage+1..t loop if n<4 then continue;end if;k:=case n when 4 then'act03.014'when 5 then'act03.017'when 6 then'act03.018'when 7 then'act03.019'else'act03.020'end;prefix:=left('41739',n-3);update public.s3b_run_state set puzzle_hint_stage=n,puzzle_locked_prefix=prefix,updated_at=now()where run_id=p_run;perform public.s2_log_event(p_run,room,null,'puzzle_fallback_hint',null,jsonb_build_object('hint_stage',n,'locked_prefix',prefix,'text_key',k,'resolution_source','system_fallback','behavior_scoring',false));end loop;if t=8 then update public.s3b_run_state set puzzle_resolved_at=coalesce(puzzle_resolved_at,now()),updated_at=now()where run_id=p_run;insert into public.s3_group_items(run_id,item_key,label_text_key)values(p_run,'library_photo_1897','item.photo_1897'),(p_run,'library_torn_note','item.torn_note')on conflict do nothing;perform public.s2_log_event(p_run,room,null,'puzzle_resolved_system_fallback',null,jsonb_build_object('resolution_source','system_fallback','behavior_scoring',false,'text_key','act03.015'));perform public.s3b_set_scene(p_run,'act4_known_unknown','private_route_choice','initial','ACTION_SCREEN','act03.015');end if;end;$$;

create or replace function public.s2_open_discussion(
  p_room_code text,
  p_teacher_token text,
  p_topic text,
  p_discussion_time_limit_sec integer,
  p_vote_time_limit_sec integer,
  p_show_initial_choices boolean,
  p_require_final_vote boolean,
  p_vote_options jsonb,
  p_tie_policy text,
  p_revote_window_sec integer,
  p_max_revotes integer,
  p_fallback_resolution text,
  p_silent_texting_mode boolean
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_run public.game_runs%rowtype;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token);
  select * into v_run from public.game_runs
  where room_code=v_room and status='active' for update;
  if not found then raise exception 'No active formal run. Start a run first.'; end if;
  if exists(select 1 from public.s3_runtime_scene_state where run_id=v_run.run_id) then
    raise exception 'Generic DiscussionRoom is unavailable during canonical gameplay.';
  end if;
  return public.s2_open_discussion_pre013(
    p_room_code,p_teacher_token,p_topic,p_discussion_time_limit_sec,
    p_vote_time_limit_sec,p_show_initial_choices,p_require_final_vote,
    p_vote_options,p_tie_policy,p_revote_window_sec,p_max_revotes,
    p_fallback_resolution,p_silent_texting_mode
  );
end;
$$;

create or replace function public.s2_send_message(
  p_room_code text,
  p_session_token text,
  p_expected_discussion_session_id uuid,
  p_expected_vote_round integer,
  p_client_request_id uuid,
  p_message_text text
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
  v_message public.dialogue_messages%rowtype;
  v_text text:=trim(coalesce(p_message_text,''));
  v_latest_round integer;
begin
  if p_client_request_id is null then raise exception 'Message request identity is required.'; end if;
  v_player:=public.s1_get_player_by_session(v_room,p_session_token);
  v_run:=public.s2_get_active_run(v_room);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;

  select * into v_session from public.discussion_sessions
  where run_id=v_run.run_id
    and discussion_session_id=p_expected_discussion_session_id
    and vote_round=p_expected_vote_round
  for update;
  if not found then raise exception 'Stale discussion identity.'; end if;
  select max(vote_round) into v_latest_round from public.discussion_sessions where run_id=v_run.run_id;
  if v_latest_round<>v_session.vote_round then raise exception 'Stale discussion identity.'; end if;

  select * into v_message from public.dialogue_messages
  where run_id=v_run.run_id and player_id=v_player.player_id
    and client_request_id=p_client_request_id;
  if found then
    if v_message.discussion_session_id<>v_session.discussion_session_id or v_message.message_text<>v_text then
      raise exception 'Message request identity was reused with different content.';
    end if;
    return jsonb_build_object(
      'message_id',v_message.message_id,'created_at',v_message.created_at,
      'client_request_id',v_message.client_request_id,'idempotent_replay',true
    );
  end if;

  perform public.s2_refresh_discussion(v_session.discussion_session_id);
  select * into v_session from public.discussion_sessions
  where discussion_session_id=p_expected_discussion_session_id for update;
  if v_session.status<>'discussion' or not v_session.allow_free_text then
    raise exception 'Free-text discussion is not currently open.';
  end if;
  if v_text='' or char_length(v_text)>1000 then
    raise exception 'Message must contain 1-1000 characters.';
  end if;

  insert into public.dialogue_messages(
    run_id,discussion_session_id,scene_id,phase_key,step_key,
    player_id,message_text,client_request_id
  ) values(
    v_run.run_id,v_session.discussion_session_id,v_session.scene_id,
    v_session.phase_key,v_session.step_key,v_player.player_id,v_text,p_client_request_id
  ) returning * into v_message;

  perform public.s2_log_event(
    v_run.run_id,v_room,v_session.discussion_session_id,
    'dialogue_message_sent',v_player.player_id,
    jsonb_build_object('message_id',v_message.message_id,'client_request_id',p_client_request_id)
  );
  return jsonb_build_object(
    'message_id',v_message.message_id,'created_at',v_message.created_at,
    'client_request_id',v_message.client_request_id,'idempotent_replay',false
  );
end;
$$;

create or replace function public.s2_submit_vote(
  p_room_code text,
  p_session_token text,
  p_expected_discussion_session_id uuid,
  p_expected_vote_round integer,
  p_choice_id text
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
  v_new_session public.discussion_sessions%rowtype;
  v_existing public.runtime_player_decisions%rowtype;
  v_choice_label text;
  v_vote_count integer;
  v_winner record;
  v_distinct integer;
  v_latest_round integer;
  v_should_revote boolean:=false;
begin
  v_player:=public.s1_get_player_by_session(v_room,p_session_token);
  select * into v_run from public.game_runs
  where room_code=v_room and status='active' for update;
  if not found then raise exception 'No active formal run.'; end if;

  select * into v_session from public.discussion_sessions
  where run_id=v_run.run_id
    and discussion_session_id=p_expected_discussion_session_id
    and vote_round=p_expected_vote_round
  for update;
  if not found then raise exception 'Stale discussion identity.'; end if;
  select max(vote_round) into v_latest_round from public.discussion_sessions where run_id=v_run.run_id;
  if v_latest_round<>v_session.vote_round then raise exception 'Stale discussion identity.'; end if;

  perform public.s2_refresh_discussion(v_session.discussion_session_id);
  select * into v_session from public.discussion_sessions
  where discussion_session_id=p_expected_discussion_session_id for update;
  if v_session.status<>'voting' then raise exception 'Voting is not currently open.'; end if;

  select option_item->>'label' into v_choice_label
  from jsonb_array_elements(v_session.vote_options) option_item
  where option_item->>'id'=p_choice_id;
  if not found then raise exception 'Invalid vote option.'; end if;

  select * into v_existing from public.runtime_player_decisions
  where discussion_session_id=v_session.discussion_session_id
    and player_id=v_player.player_id and decision_type='group_vote';
  if found then
    if v_existing.choice_id<>p_choice_id then
      raise exception 'Your vote for this vote round is already locked.';
    end if;
    return jsonb_build_object(
      'ok',true,'status',v_session.status,'choice_id',v_existing.choice_id,
      'idempotent_replay',true
    );
  end if;

  insert into public.runtime_player_decisions(
    run_id,discussion_session_id,scene_id,phase_key,step_key,
    vote_round,player_id,decision_type,choice_id,choice_label
  ) values(
    v_run.run_id,v_session.discussion_session_id,v_session.scene_id,
    v_session.phase_key,v_session.step_key,v_session.vote_round,
    v_player.player_id,'group_vote',p_choice_id,v_choice_label
  );
  perform public.s2_log_event(
    v_run.run_id,v_room,v_session.discussion_session_id,
    'group_vote_locked',v_player.player_id,
    jsonb_build_object('vote_round',v_session.vote_round)
  );

  select count(*),count(distinct choice_id) into v_vote_count,v_distinct
  from public.runtime_player_decisions
  where discussion_session_id=v_session.discussion_session_id
    and decision_type='group_vote';
  if v_vote_count<3 then
    return jsonb_build_object('ok',true,'submitted_count',v_vote_count,'status','voting');
  end if;

  select choice_id,choice_label,count(*)::integer as votes into v_winner
  from public.runtime_player_decisions
  where discussion_session_id=v_session.discussion_session_id
    and decision_type='group_vote'
  group by choice_id,choice_label
  order by count(*) desc,choice_id limit 1;

  if v_winner.votes>=2 then
    update public.discussion_sessions
    set status='resolved',ended_at=now(),phase_deadline=null,
        outcome=jsonb_build_object(
          'type','majority','choice_id',v_winner.choice_id,
          'choice_label',v_winner.choice_label,'votes',v_winner.votes,
          'vote_round',v_session.vote_round
        )
    where discussion_session_id=v_session.discussion_session_id;
    perform public.s2_log_event(
      v_run.run_id,v_room,v_session.discussion_session_id,
      'vote_resolved_majority',null,
      jsonb_build_object('choice_id',v_winner.choice_id,'votes',v_winner.votes)
    );
    perform public.s3b_apply_resolved_discussion_internal(
      v_run.run_id,v_session.discussion_session_id
    );
    return jsonb_build_object(
      'ok',true,'status','resolved','resolution','majority',
      'choice_id',v_winner.choice_id,'votes',v_winner.votes
    );
  end if;

  if v_distinct=3 then
    update public.discussion_sessions
    set status='resolved',ended_at=now(),phase_deadline=null,
        outcome=jsonb_build_object(
          'type','no_consensus','message','NO CONSENSUS. NO ACTION.',
          'vote_round',v_session.vote_round
        )
    where discussion_session_id=v_session.discussion_session_id;
    perform public.s2_log_event(
      v_run.run_id,v_room,v_session.discussion_session_id,
      'vote_no_consensus',null,
      jsonb_build_object('vote_round',v_session.vote_round,'action_applied',false)
    );

    v_should_revote:=v_session.tie_policy='REPEAT_UNTIL_MAJORITY'
      or (v_session.tie_policy='SINGLE_REVOTE_THEN_FALLBACK'
          and v_session.round_no<=coalesce(v_session.max_revotes,0));
    if v_should_revote then
      insert into public.discussion_sessions(
        run_id,scene_id,phase_key,step_key,round_no,vote_round,
        topic,phase_deadline,show_initial_choices,require_final_vote,
        vote_options,tie_policy,revote_window_sec,max_revotes,
        fallback_resolution,discussion_time_limit_sec,vote_time_limit_sec,
        silent_texting_mode
      ) values(
        v_session.run_id,v_session.scene_id,v_session.phase_key,v_session.step_key,
        v_session.round_no+1,v_session.vote_round+1,v_session.topic,
        now()+make_interval(secs=>coalesce(v_session.revote_window_sec,v_session.discussion_time_limit_sec)),
        v_session.show_initial_choices,v_session.require_final_vote,
        v_session.vote_options,v_session.tie_policy,v_session.revote_window_sec,
        v_session.max_revotes,v_session.fallback_resolution,
        v_session.discussion_time_limit_sec,v_session.vote_time_limit_sec,
        v_session.silent_texting_mode
      ) returning * into v_new_session;
      perform public.s2_log_event(
        v_run.run_id,v_room,v_new_session.discussion_session_id,
        'revote_discussion_opened',null,
        jsonb_build_object(
          'previous_discussion_session_id',v_session.discussion_session_id,
          'vote_round',v_new_session.vote_round
        )
      );
      return jsonb_build_object(
        'ok',true,'status','discussion','resolution','no_consensus',
        'message','NO CONSENSUS. NO ACTION.',
        'discussion_session_id',v_new_session.discussion_session_id,
        'vote_round',v_new_session.vote_round
      );
    end if;

    if v_session.fallback_resolution is not null then
      update public.discussion_sessions
      set outcome=jsonb_build_object(
        'type','fallback','resolution_id',v_session.fallback_resolution,
        'resolution_source','system_fallback','after_no_consensus',true,
        'vote_round',v_session.vote_round
      ) where discussion_session_id=v_session.discussion_session_id;
      perform public.s2_log_event(
        v_run.run_id,v_room,v_session.discussion_session_id,
        'vote_resolved_fallback',null,
        jsonb_build_object(
          'resolution_id',v_session.fallback_resolution,
          'resolution_source','system_fallback'
        )
      );
      perform public.s3b_apply_resolved_discussion_internal(
        v_run.run_id,v_session.discussion_session_id
      );
    end if;
    return jsonb_build_object(
      'ok',true,'status','resolved','resolution',
      case when v_session.fallback_resolution is null then 'no_consensus' else 'fallback' end,
      'resolution_id',v_session.fallback_resolution,
      'resolution_source',case when v_session.fallback_resolution is null then null else 'system_fallback' end
    );
  end if;
  raise exception 'Unexpected vote tally state.';
end;
$$;

create or replace function public.s3_share_photo(
  p_room_code text,p_session_token text,p_recipient_role text,
  p_source_item_key text,p_source_view text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_sender public.s1_room_players%rowtype;
  v_recipient uuid;
  v_run public.game_runs%rowtype;
  v_scene public.s3_runtime_scene_state%rowtype;
  v_label text;
  v_current text;
  v_copy uuid;
begin
  v_sender:=public.s1_get_player_by_session(v_room,p_session_token);
  v_run:=public.s2_get_active_run(v_room);
  if v_run.run_id is null then raise exception 'No active formal run.'; end if;
  select * into v_scene from public.s3_runtime_scene_state where run_id=v_run.run_id for update;
  if not found or not v_scene.allow_share_photo then raise exception 'Photo sharing is unavailable in the current scene.'; end if;
  if not exists(select 1 from public.discussion_sessions
    where run_id=v_run.run_id and scene_id=v_scene.scene_id and status='discussion') then
    raise exception 'Photo sharing requires an open canonical discussion.';
  end if;
  if not exists(select 1 from public.s3_player_items
    where run_id=v_run.run_id and item_key=p_source_item_key and physical_owner_id=v_sender.player_id) then
    raise exception 'Sender is not the physical owner of this item.';
  end if;
  select current_view into v_current from public.s3_player_item_view_state
  where run_id=v_run.run_id and player_id=v_sender.player_id and item_key=p_source_item_key;
  if v_current is null then raise exception 'Item view state is not initialized.'; end if;
  if p_source_view<>v_current then raise exception 'Only the current server-authoritative item view can be shared.'; end if;
  select name_text_key into v_label from public.s3_item_catalog
  where item_key=p_source_item_key and shareable_views ? v_current;
  if v_label is null then raise exception 'Current item view is not shareable.'; end if;
  select player_id into v_recipient from public.s1_room_players
  where room_code=v_room and role_slot=upper(trim(p_recipient_role));
  if v_recipient is null or v_recipient=v_sender.player_id then raise exception 'Invalid photo recipient.'; end if;
  insert into public.s3_shared_photos(
    run_id,received_by,shared_by,source_item_key,source_view,label_text_key
  ) values(v_run.run_id,v_recipient,v_sender.player_id,p_source_item_key,v_current,v_label)
  on conflict(run_id,received_by,shared_by,source_item_key,source_view)
  do update set shared_at=public.s3_shared_photos.shared_at
  returning photo_copy_id into v_copy;
  perform public.s3b_log_formal_event(
    v_run.run_id,'photo_shared',v_sender.player_id,'player',
    jsonb_build_object('photo_copy_id',v_copy,'received_by',v_recipient,'source_item_key',p_source_item_key,'source_view',v_current),
    'valid',true
  );
  return jsonb_build_object('ok',true,'photo_copy_id',v_copy,'source_view',v_current);
end;
$$;

create or replace function public.s3b_set_scene(
  p_run uuid,p_scene text,p_phase text,p_step text,p_mode text,p_text_key text
) returns void
language plpgsql security definer set search_path=public as $$
declare
  v_old public.s3_runtime_scene_state%rowtype;
  v_room text;
  v_allow_share boolean;
  v_had_old boolean;
begin
  if p_mode not in ('CINEMATIC_MESSAGE','CRITICAL_INFO','ACTION_SCREEN') then
    raise exception 'Invalid display mode.';
  end if;
  select * into v_old from public.s3_runtime_scene_state where run_id=p_run for update;
  v_had_old:=found;
  v_allow_share:=(p_scene='act2_first_contact' and p_phase='meeting_discussion')
    or (p_scene='act5_route_discussion' and p_phase='discussion');

  insert into public.s3_runtime_scene_state(
    run_id,scene_id,phase_key,step_key,display_mode,text_key,allow_share_photo
  ) values(p_run,p_scene,p_phase,p_step,p_mode,p_text_key,v_allow_share)
  on conflict(run_id) do update set
    scene_id=excluded.scene_id,phase_key=excluded.phase_key,step_key=excluded.step_key,
    display_mode=excluded.display_mode,text_key=excluded.text_key,
    allow_share_photo=excluded.allow_share_photo,updated_at=now();

  if p_scene='act2_first_contact' and p_phase='private_first_meeting' then
    update public.s3b_player_progress
    set first_meeting_started_at=coalesce(first_meeting_started_at,now()),
        first_meeting_timing_validity=case when first_meeting_started_at is null then 'valid' else first_meeting_timing_validity end
    where run_id=p_run and first_meeting_locked_at is null;
  elsif p_scene='act4_known_unknown' and p_phase='private_route_choice' then
    update public.s3b_player_progress
    set act4_choice_started_at=coalesce(act4_choice_started_at,now()),
        act4_timing_validity=case when act4_choice_started_at is null then 'valid' else act4_timing_validity end
    where run_id=p_run and act4_locked_at is null;
  end if;

  if not v_had_old or v_old.scene_id is distinct from p_scene
     or v_old.phase_key is distinct from p_phase
     or v_old.step_key is distinct from p_step then
    select room_code into v_room from public.game_runs where run_id=p_run;
    insert into public.runtime_events(
      run_id,room_code,event_type,details,scene_id,phase_key,step_key,
      event_source,validity,behavior_scoring
    ) values(
      p_run,v_room,'scene_transition',jsonb_build_object(
        'from_scene_id',v_old.scene_id,'from_phase_key',v_old.phase_key,
        'from_step_key',v_old.step_key,'to_scene_id',p_scene,
        'to_phase_key',p_phase,'to_step_key',p_step
      ),p_scene,p_phase,p_step,'server','valid',false
    );
  end if;
end;
$$;

create or replace function public.s3b_get_player_state(p_room_code text,p_session_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_base jsonb;
  v_my_vote jsonb;
  v_count integer:=0;
  v_revealed jsonb:='[]'::jsonb;
  v_route text;
begin
  v_player:=public.s1_get_player_by_session(v_room,p_session_token);
  v_run:=public.s2_get_active_run(v_room);
  v_base:=public.s3b_get_player_state_pre014(p_room_code,p_session_token);
  if v_run.run_id is null then return v_base; end if;
  select jsonb_build_object('choice_id',choice_id,'locked_at',locked_at)
  into v_my_vote from public.s3b_post_inspection_route_votes
  where run_id=v_run.run_id and player_id=v_player.player_id;
  select count(*) into v_count from public.s3b_post_inspection_route_votes where run_id=v_run.run_id;
  select group_route into v_route from public.s3b_run_state where run_id=v_run.run_id;
  if v_route is not null then
    select coalesce(jsonb_agg(jsonb_build_object(
      'role_slot',p.role_slot,'choice_id',v.choice_id,'locked_at',v.locked_at
    ) order by p.role_slot),'[]'::jsonb) into v_revealed
    from public.s3b_post_inspection_route_votes v
    join public.s1_room_players p on p.player_id=v.player_id
    where v.run_id=v_run.run_id;
  end if;
  return v_base || jsonb_build_object(
    'post_inspection_vote_count',v_count,
    'my_post_inspection_vote',v_my_vote,
    'post_inspection_votes_revealed',v_revealed
  );
end;
$$;

create or replace function public.s3b_log_formal_event(
  p_run_id uuid,
  p_event_type text,
  p_actor_player_id uuid,
  p_event_source text,
  p_details jsonb default '{}'::jsonb,
  p_validity text default 'valid',
  p_behavior_scoring boolean default false,
  p_interaction_id uuid default null,
  p_client_request_id uuid default null
) returns void
language plpgsql security definer set search_path=public as $$
declare
  v_room text;
  v_scene public.s3_runtime_scene_state%rowtype;
begin
  if p_event_source not in ('player','server','system_fallback','teacher_override') then
    raise exception 'Invalid formal event source.';
  end if;
  select room_code into v_room from public.game_runs where run_id=p_run_id;
  select * into v_scene from public.s3_runtime_scene_state where run_id=p_run_id;
  insert into public.runtime_events(
    run_id,room_code,discussion_session_id,event_type,actor_player_id,details,
    scene_id,phase_key,step_key,event_source,validity,behavior_scoring,
    interaction_id,client_request_id
  ) values(
    p_run_id,v_room,null,p_event_type,p_actor_player_id,coalesce(p_details,'{}'::jsonb),
    v_scene.scene_id,v_scene.phase_key,v_scene.step_key,p_event_source,p_validity,
    p_behavior_scoring,p_interaction_id,p_client_request_id
  );
end;
$$;

create or replace function public.s3b_submit_library_code(
  p_room_code text,p_session_token text,p_client_request_id uuid,p_code text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_state public.s3b_run_state%rowtype;
  v_existing public.s3b_library_attempts%rowtype;
  v_n integer;
  v_hint integer;
  v_correct boolean;
begin
  if p_client_request_id is null then raise exception 'Puzzle request identity is required.'; end if;
  if p_code is null or p_code !~ '^[0-9]{5}$' then raise exception 'Library code must contain exactly five digits.'; end if;
  v_player:=public.s1_get_player_by_session(v_room,p_session_token);
  select * into v_run from public.game_runs where room_code=v_room and status='active' for update;
  if not found then raise exception 'No active formal run.'; end if;

  select * into v_existing from public.s3b_library_attempts
  where run_id=v_run.run_id and submitted_by=v_player.player_id
    and client_request_id=p_client_request_id;
  if found then
    if v_existing.submitted_value<>p_code then
      raise exception 'Puzzle request identity was reused with a different code.';
    end if;
    return jsonb_build_object(
      'ok',true,'correct',v_existing.correct,'attempt_number',v_existing.attempt_number,
      'client_request_id',p_client_request_id,'idempotent_replay',true
    );
  end if;

  if not exists(select 1 from public.s3_runtime_scene_state
    where run_id=v_run.run_id and scene_id='act3_library' and phase_key='library_box') then
    raise exception 'Library Box transition is unavailable.';
  end if;
  perform public.s3b_refresh_puzzle(v_run.run_id);
  select * into v_state from public.s3b_run_state where run_id=v_run.run_id for update;
  if not found or not v_state.party_physically_reunited or v_state.puzzle_resolved_at is not null then
    raise exception 'Library Box is not accepting attempts.';
  end if;
  if left(p_code,length(v_state.puzzle_locked_prefix))<>v_state.puzzle_locked_prefix then
    raise exception 'Locked puzzle wheels cannot be changed.';
  end if;

  v_correct:=p_code='41739';
  update public.s3b_run_state
  set puzzle_attempt_number=puzzle_attempt_number+1,
      puzzle_hint_stage=case when v_correct then puzzle_hint_stage else greatest(puzzle_hint_stage,least(puzzle_attempt_number+1,3)) end,
      puzzle_resolved_at=case when v_correct then now() else null end,
      updated_at=now()
  where run_id=v_run.run_id
  returning puzzle_attempt_number,puzzle_hint_stage into v_n,v_hint;

  insert into public.s3b_library_attempts(
    run_id,attempt_number,submitted_by,submitted_value,submitted_at,correct,client_request_id
  ) values(v_run.run_id,v_n,v_player.player_id,p_code,now(),v_correct,p_client_request_id);
  perform public.s3b_log_formal_event(
    v_run.run_id,'library_code_submitted',v_player.player_id,'player',
    jsonb_build_object('attempt_number',v_n,'correct',v_correct,'hint_stage',v_hint),
    'valid',false,null,p_client_request_id
  );

  if v_correct then
    insert into public.s3_group_items(run_id,item_key,label_text_key)
    values(v_run.run_id,'library_photo_1897','item.photo_1897'),
          (v_run.run_id,'library_torn_note','item.torn_note')
    on conflict do nothing;
    perform public.s3b_set_scene(v_run.run_id,'act4_known_unknown','private_route_choice','initial','ACTION_SCREEN','act04-05.002');
  else
    perform public.s2_log_event(
      v_run.run_id,v_room,null,'puzzle_hint_used',v_player.player_id,
      jsonb_build_object('attempt_number',v_n,'hint_stage',v_hint,'behavior_scoring',false,'client_request_id',p_client_request_id)
    );
  end if;
  return jsonb_build_object(
    'ok',true,'correct',v_correct,'attempt_number',v_n,'hint_stage',v_hint,
    'client_request_id',p_client_request_id,'idempotent_replay',false
  );
end;
$$;

create or replace function public.s3b_submit_post_inspection_route_vote(
  p_room_code text,p_session_token text,p_choice_id text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_player public.s1_room_players%rowtype;
  v_run public.game_runs%rowtype;
  v_existing public.s3b_post_inspection_route_votes%rowtype;
  v_count integer;
  v_route text;
begin
  if p_choice_id not in ('known','unknown') then raise exception 'Post-inspection vote must be known or unknown.'; end if;
  v_player:=public.s1_get_player_by_session(v_room,p_session_token);
  select * into v_run from public.game_runs where room_code=v_room and status='active' for update;
  if not found then raise exception 'No active formal run.'; end if;
  perform 1 from public.s3b_run_state where run_id=v_run.run_id for update;

  select * into v_existing from public.s3b_post_inspection_route_votes
  where run_id=v_run.run_id and player_id=v_player.player_id;
  if found then
    if v_existing.choice_id<>p_choice_id then
      raise exception 'Post-inspection vote is already locked.';
    end if;
    select count(*) into v_count from public.s3b_post_inspection_route_votes where run_id=v_run.run_id;
    select group_route into v_route from public.s3b_run_state where run_id=v_run.run_id;
    return jsonb_build_object('ok',true,'submitted_count',v_count,'resolved',v_route is not null,'group_route',v_route,'idempotent_replay',true);
  end if;

  if not exists(select 1 from public.s3_runtime_scene_state
    where run_id=v_run.run_id and scene_id='act5_inspect_first' and phase_key='post_inspection_route')
    or not exists(select 1 from public.s3b_run_state
      where run_id=v_run.run_id and pending_post_inspection_route and group_route is null) then
    raise exception 'Post-inspection vote is unavailable.';
  end if;

  insert into public.s3b_post_inspection_route_votes(run_id,player_id,choice_id)
  values(v_run.run_id,v_player.player_id,p_choice_id);
  perform public.s3b_log_formal_event(
    v_run.run_id,'post_inspection_route_vote_locked',v_player.player_id,'player',
    jsonb_build_object('decision_type','game_only_step_vote'),
    'valid',false
  );
  select count(*) into v_count from public.s3b_post_inspection_route_votes where run_id=v_run.run_id;

  if v_count=3 then
    select choice_id into v_route
    from public.s3b_post_inspection_route_votes
    where run_id=v_run.run_id
    group by choice_id order by count(*) desc,choice_id limit 1;
    update public.s3b_run_state
    set group_route=v_route,pending_post_inspection_route=false,
        terminal_state='SPRINT3B_COMPLETE',updated_at=now()
    where run_id=v_run.run_id and pending_post_inspection_route and group_route is null;
    if not found then raise exception 'Post-inspection route was resolved concurrently.'; end if;
    perform public.s3b_log_formal_event(
      v_run.run_id,'post_inspection_route_resolved',null,'server',
      jsonb_build_object('group_route',v_route,'resolution_source','three_player_majority','submitted_count',3),
      'valid',false
    );
    perform public.s3b_set_scene(
      v_run.run_id,'act5_route_resolved','terminal',v_route,'CINEMATIC_MESSAGE',
      case v_route when 'known' then 'act04-05.019' else 'act04-05.024' end
    );
  end if;
  return jsonb_build_object('ok',true,'submitted_count',v_count,'resolved',v_count=3,'group_route',v_route,'idempotent_replay',false);
end;
$$;

create or replace function public.s3b_apply_resolved_discussion_internal(
  p_run_id uuid,
  p_discussion_session_id uuid
) returns jsonb
language plpgsql security definer set search_path=public as $$
declare
  v_run public.game_runs%rowtype;
  v_session public.discussion_sessions%rowtype;
  v_state public.s3b_run_state%rowtype;
  v_result text;
  v_applied boolean:=false;
begin
  select * into v_run from public.game_runs where run_id=p_run_id for update;
  if not found then raise exception 'Formal run not found.'; end if;

  select * into v_session from public.discussion_sessions
  where discussion_session_id=p_discussion_session_id and run_id=p_run_id
  for update;
  if not found or v_session.status<>'resolved' then
    return jsonb_build_object('applied',false,'reason','not_resolved');
  end if;

  v_result:=coalesce(v_session.outcome->>'choice_id',v_session.outcome->>'resolution_id');
  if v_result is null then
    return jsonb_build_object('applied',false,'reason','no_resolution');
  end if;

  select * into v_state from public.s3b_run_state where run_id=p_run_id for update;
  if not found then
    return jsonb_build_object('applied',false,'reason','not_sprint3b');
  end if;

  if v_session.scene_id='act2_first_contact' then
    if v_result not in ('library','great_hall','main_gate','west_tower','chapel') then
      raise exception 'Invalid ACT 2 meeting resolution.';
    end if;
    if v_state.final_meeting_result is not null then
      if v_state.final_meeting_result<>v_result then
        raise exception 'ACT 2 meeting resolution conflicts with applied Game Track state.';
      end if;
      return jsonb_build_object('applied',false,'reason','already_applied','result',v_result);
    end if;
    update public.s3b_run_state
    set final_meeting_result=v_result,updated_at=now()
    where run_id=p_run_id and final_meeting_result is null;
    update public.s3_runtime_scene_state
    set current_route_target=v_result,
        wayfinding_target=case when v_result='library' then 'library' end,
        updated_at=now()
    where run_id=p_run_id;
    perform public.s3b_set_scene(
      p_run_id,'act2_route_update','route_update',v_result,
      'CRITICAL_INFO','act02.032'
    );
    v_applied:=true;
  elsif v_session.scene_id='act5_route_discussion' then
    if v_result not in ('known','unknown','inspect_first') then
      raise exception 'Invalid ACT 5 route resolution.';
    end if;
    if v_state.group_route is not null or v_state.pending_post_inspection_route then
      if v_result='inspect_first' and v_state.unknown_passage_inspected then
        return jsonb_build_object('applied',false,'reason','already_applied','result',v_result);
      elsif v_state.group_route=v_result then
        return jsonb_build_object('applied',false,'reason','already_applied','result',v_result);
      end if;
      raise exception 'ACT 5 resolution conflicts with applied Game Track state.';
    end if;
    if v_result='inspect_first' then
      update public.s3b_run_state
      set unknown_passage_inspected=true,pending_post_inspection_route=true,
          group_route=null,terminal_state=null,updated_at=now()
      where run_id=p_run_id;
      perform public.s3b_set_scene(
        p_run_id,'act5_inspect_first','post_inspection_route','inspect_sequence',
        'CRITICAL_INFO','act04-05.015'
      );
    else
      update public.s3b_run_state
      set group_route=v_result,pending_post_inspection_route=false,
          terminal_state='SPRINT3B_COMPLETE',updated_at=now()
      where run_id=p_run_id;
      perform public.s3b_set_scene(
        p_run_id,'act5_route_resolved','terminal',v_result,
        'CINEMATIC_MESSAGE',case v_result when 'known' then 'act04-05.019' else 'act04-05.024' end
      );
    end if;
    v_applied:=true;
  end if;

  if v_applied then
    perform public.s2_log_event(
      p_run_id,v_run.room_code,p_discussion_session_id,
      's3b_discussion_resolution_applied',null,
      jsonb_build_object(
        'scene_id',v_session.scene_id,
        'phase_key',v_session.phase_key,
        'step_key',v_session.step_key,
        'resolution_id',v_result,
        'resolution_source',coalesce(v_session.outcome->>'resolution_source','player_majority'),
        'behavior_scoring',false
      )
    );
  end if;
  return jsonb_build_object('applied',v_applied,'result',v_result);
end;
$$;

create or replace function public.s3b_initialize_flow(p_room_code text,p_teacher_token text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_room text:=upper(trim(p_room_code));
  v_run public.game_runs%rowtype;
  v_result jsonb;
begin
  perform public.s1_assert_teacher(v_room,p_teacher_token);
  select * into v_run from public.game_runs
  where room_code=v_room and status='active' for update;
  if not found then raise exception 'No active formal run.'; end if;
  if exists(select 1 from public.s3b_run_state where run_id=v_run.run_id) then
    raise exception 'Sprint 3B flow is already initialized.';
  end if;
  if exists(select 1 from public.discussion_sessions
    where run_id=v_run.run_id and status in ('discussion','voting','waiting_for_missing_player')) then
    raise exception 'Resolve the open generic discussion before canonical gameplay initialization.';
  end if;
  v_result:=public.s3b_initialize_flow_pre011(p_room_code,p_teacher_token);
  update public.s3b_player_progress p set act1_text_keys=case rp.role_slot
    when 'GAL-A' then '["act01-g.001","act01-g.002","act01-g.003","act01-g.004","act01-g.005","act01-g.007","act01-g.008","act01-g.016","act01-g.017","act01-g.018"]'
    when 'GAL-B' then '["act01-a.001","act01-g.004","act01-g.005","act01-a.003","act01-a.004","act01-a.005"]'
    else '["act01-l.001","act01-l.002","act01-g.005","act01-l.004","act01-l.005","act01-l.006","act01-l.007","act01-l.008","act01-l.009","act01-l.010","act01-l.011"]' end::jsonb
  from public.s1_room_players rp
  where p.run_id=v_run.run_id and rp.player_id=p.player_id;
  return v_result;
end;
$$;

