create or replace function public.s3b_log_formal_event_at_context(
  p_run_id uuid,p_event_type text,p_actor_player_id uuid,p_event_source text,
  p_scene_id text,p_phase_key text,p_step_key text,p_details jsonb default '{}'::jsonb,
  p_validity text default 'valid',p_behavior_scoring boolean default false,
  p_interaction_id uuid default null,p_client_request_id uuid default null
) returns void language plpgsql security definer set search_path=public as $$
declare v_room text;v_override public.teacher_overrides%rowtype;v_details jsonb:=coalesce(p_details,'{}'::jsonb);
begin
  if p_event_source not in ('player','server','system_fallback','teacher_override') then raise exception 'Invalid formal event source.';end if;
  select room_code into v_room from public.game_runs where run_id=p_run_id;
  select o.* into v_override from public.game_runs g join public.teacher_overrides o on o.override_id=g.active_override_id where g.run_id=p_run_id;
  if v_override.override_id is not null then
    v_details:=v_details||jsonb_build_object('context_provenance',jsonb_build_object(
      'upstream_teacher_override',true,'override_id',v_override.override_id,
      'source_scene',v_override.source_scene,'source_phase',v_override.source_phase,
      'override_action',v_override.override_action));
  end if;
  insert into public.runtime_events(run_id,room_code,discussion_session_id,event_type,actor_player_id,details,scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id,client_request_id)
  values(p_run_id,v_room,null,p_event_type,p_actor_player_id,v_details,p_scene_id,p_phase_key,p_step_key,p_event_source,p_validity,p_behavior_scoring,p_interaction_id,p_client_request_id);
end;$$;

create or replace function public.s2_log_event(
  p_run_id uuid,p_room_code text,p_discussion_session_id uuid,p_event_type text,
  p_actor_player_id uuid,p_details jsonb default '{}'::jsonb
) returns void language plpgsql security definer set search_path=public as $$
declare
  v_scene text;
  v_phase text;
  v_step text;
  v_override public.teacher_overrides%rowtype;
  v_details jsonb:=coalesce(p_details,'{}'::jsonb);
begin
  if p_discussion_session_id is not null then
    select scene_id,phase_key,step_key into v_scene,v_phase,v_step
    from public.discussion_sessions
    where discussion_session_id=p_discussion_session_id;
  end if;
  if v_scene is null then
    select scene_id,phase_key,step_key into v_scene,v_phase,v_step
    from public.s3_runtime_scene_state where run_id=p_run_id;
  end if;
  select o.* into v_override from public.game_runs g
  join public.teacher_overrides o on o.override_id=g.active_override_id
  where g.run_id=p_run_id;
  if v_override.override_id is not null then
    v_details:=v_details||jsonb_build_object(
      'context_provenance',jsonb_build_object(
        'upstream_teacher_override',true,'override_id',v_override.override_id,
        'source_scene',v_override.source_scene,'source_phase',v_override.source_phase,
        'override_action',v_override.override_action));
  end if;
  insert into public.runtime_events(
    run_id,room_code,discussion_session_id,event_type,actor_player_id,details,
    scene_id,phase_key,step_key,event_source,validity,behavior_scoring,interaction_id,
    client_request_id
  ) values(
    p_run_id,upper(trim(p_room_code)),p_discussion_session_id,p_event_type,
    p_actor_player_id,v_details,v_scene,v_phase,v_step,
    case when p_actor_player_id is null then 'server' else 'player' end,
    coalesce(p_details->>'validity','valid'),
    case when p_details ? 'behavior_scoring' then (p_details->>'behavior_scoring')::boolean end,
    p_discussion_session_id,
    case when p_details ? 'client_request_id' then (p_details->>'client_request_id')::uuid end);
end;
$$;

create or replace function public.s3b_submit_first_meeting(
  p_room_code text,p_session_token text,p_choice_id text
) returns jsonb language plpgsql security definer set search_path=public as $$
declare
  r text:=upper(trim(p_room_code));
  p public.s1_room_players%rowtype;
  g public.game_runs%rowtype;
  s public.s3_runtime_scene_state%rowtype;
  progress public.s3b_player_progress%rowtype;
  validity text;
  duration_ms bigint;
begin
  if p_choice_id not in ('library','great_hall','main_gate','west_tower','chapel','help') then
    raise exception 'Invalid ACT 2 first-meeting choice.';
  end if;
  p:=public.s1_get_player_by_session(r,p_session_token);
  select * into g from public.game_runs
  where room_code=r and status='active' for update;
  if not found then raise exception 'No active formal run.';end if;
  select * into s from public.s3_runtime_scene_state where run_id=g.run_id;
  if s.scene_id<>'act2_first_contact' or s.phase_key<>'private_first_meeting' then
    raise exception 'ACT 2 first meeting transition is unavailable.';
  end if;
  select * into progress from public.s3b_player_progress
  where run_id=g.run_id and player_id=p.player_id for update;
  if progress.act1_stage<>'complete' then raise exception 'ACT 1 is not complete.';end if;
  if progress.first_meeting_choice is not null then
    raise exception 'ACT 2 first meeting transition is unavailable.';
  end if;
  validity:=case when progress.first_meeting_started_at is null then 'legacy_missing_start' else 'valid' end;
  duration_ms:=case when progress.first_meeting_started_at is null then null
    else round(extract(epoch from(now()-progress.first_meeting_started_at))*1000)::bigint end;
  perform public.s3b_log_formal_event_at_context(
    g.run_id,'first_meeting_choice_locked',p.player_id,'player',
    s.scene_id,s.phase_key,s.step_key,
    jsonb_build_object('choice_id',p_choice_id,'response_duration_ms',duration_ms),
    validity,true);
  update public.s3b_player_progress
  set first_meeting_choice=p_choice_id,first_meeting_locked_at=now(),
      first_meeting_timing_validity=validity
  where run_id=g.run_id and player_id=p.player_id;
  return jsonb_build_object('ok',true);
end;
$$;

create or replace function public.asset_manager_register_candidate(p_teacher_token text,p_candidate jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.asset_registry_projection%rowtype;id uuid;v int;anchors jsonb;
begin
 if not exists(select 1 from public.s1_rooms where teacher_token_hash=public.s1_hash_token(p_teacher_token)) then raise exception 'Invalid teacher authority.';end if;
 select * into r from public.asset_registry_projection where asset_key=p_candidate->>'asset_key' for update;if not found then raise exception 'ASSET KEY NOT FOUND';end if;
 v:=(p_candidate->>'version')::int;if v<>r.latest_version then raise exception 'Candidate version disagrees with canonical registry.';end if;
 if p_candidate->>'asset_type'<>r.asset_type or p_candidate->>'sha256'!~'^[0-9a-f]{64}$' then raise exception 'Candidate identity or checksum mismatch.';end if;
 anchors:=coalesce(p_candidate->'ui_anchors','[]');
 insert into public.asset_candidates(asset_key,version,asset_type,scene_id,assigned_to,creator,storage_path,status,final_prompt,revision_note,technical_notes,paired_asset_group,view_name,ui_anchors,width_px,height_px,mime_type,duration_ms,loopable,license_source,loudness_note,continuity_refs,required_anchors,sha256)
 values(r.asset_key,v,r.asset_type,p_candidate->>'scene_id',p_candidate->>'assigned_to',coalesce(p_candidate->>'creator','VA'),p_candidate->>'storage_path','PENDING_REVIEW',p_candidate->>'final_prompt',p_candidate->>'revision_note',p_candidate->>'technical_notes',r.paired_asset_group,p_candidate->>'view_name',anchors,(p_candidate->>'width_px')::int,(p_candidate->>'height_px')::int,p_candidate->>'mime_type',(p_candidate->>'duration_ms')::int,(p_candidate->>'loopable')::boolean,p_candidate->>'license_source',p_candidate->>'loudness_note',r.continuity_refs,r.required_anchors,p_candidate->>'sha256') returning asset_id into id;
 insert into public.asset_events values(default,r.asset_key,'candidate_registered',v,jsonb_build_object('asset_id',id),default);return jsonb_build_object('ok',true,'asset_id',id);
end$$;

create or replace function public.asset_manager_mark_published(p_teacher_token text,p_asset_id uuid,p_storage_path text,p_sha256 text)
returns jsonb language plpgsql security definer set search_path=public as $$ declare c public.asset_candidates%rowtype;
begin if not exists(select 1 from public.s1_rooms where teacher_token_hash=public.s1_hash_token(p_teacher_token)) then raise exception 'Invalid teacher authority.';end if;select * into c from public.asset_candidates where asset_id=p_asset_id for update;
 if c.status<>'APPROVED' or c.sha256<>p_sha256 or p_storage_path is null then raise exception 'Only checksum-matching APPROVED candidates may publish.';end if;
 update public.asset_candidates set storage_path=p_storage_path,published_at=now() where asset_id=p_asset_id;insert into public.asset_events values(default,c.asset_key,'published',c.version,jsonb_build_object('storage_path',p_storage_path),default);return jsonb_build_object('ok',true);end$$;

create or replace function public.asset_resolve(p_asset_key text) returns jsonb language plpgsql security definer set search_path=public as $$ declare r public.asset_registry_projection%rowtype;c public.asset_candidates%rowtype;
begin select * into r from public.asset_registry_projection where asset_key=p_asset_key;if not found then return jsonb_build_object('ok',false,'fallback',true,'reason','ASSET_KEY_NOT_FOUND','asset_key',p_asset_key);end if;
 select * into c from public.asset_candidates where asset_key=p_asset_key and version=r.active_version and status='ACTIVE';if not found then insert into public.asset_events(asset_key,event_type,version,details)values(r.asset_key,'asset_load_failed',r.active_version,jsonb_build_object('reason','NO_ACTIVE_ASSET'));return jsonb_build_object('ok',false,'fallback',true,'reason','NO_ACTIVE_ASSET','asset_key',r.asset_key,'asset_type',r.asset_type);end if;
 return jsonb_build_object('ok',true,'asset_key',c.asset_key,'asset_type',c.asset_type,'version',c.version,'storage_path',c.storage_path,'ui_anchors',c.ui_anchors,'width_px',c.width_px,'height_px',c.height_px,'mime_type',c.mime_type,'duration_ms',c.duration_ms,'loopable',c.loopable);end$$;
